import{_ as t,o as r,c as i,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"D4N in RGW - Pritha Srivastava, IBM","description":"","frontmatter":{"title":"D4N in RGW - Pritha Srivastava, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","RGW","D4N缓存","分布式存储","Ceph RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/D4N_in_RGW_-_Pritha_Srivastava_IBM.md","filePath":"posts/2025/D4N_in_RGW_-_Pritha_Srivastava_IBM.md","lastUpdated":1780459816000}'),l={name:"posts/2025/D4N_in_RGW_-_Pritha_Srivastava_IBM.md"};function o(s,a,n,h,d,g){return r(),i("div",null,[...a[0]||(a[0]=[e('<h3 id="会议纪要-ceph-rgw-d4n-缓存功能介绍" tabindex="-1">会议纪要：Ceph RGW D4N 缓存功能介绍 <a class="header-anchor" href="#会议纪要-ceph-rgw-d4n-缓存功能介绍" aria-label="Permalink to &quot;会议纪要：Ceph RGW D4N 缓存功能介绍&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph RGW D4N 缓存功能的介绍与进展</p><p><strong>主讲人</strong>: Pra Shasta, IBM SEF RGW 团队</p><p><strong>会议时间</strong>: 未知</p><h4 id="背景介绍" tabindex="-1">背景介绍 <a class="header-anchor" href="#背景介绍" aria-label="Permalink to &quot;背景介绍&quot;">​</a></h4><p>D4N (Directory-based Data Center Data Delivery Network) 是 Ceph RGW 中即将引入的新功能，旨在通过智能预取（Karis Prefecture）提升数据存储和访问的效率。D4N 是 D3N 缓存的继任者，设计更贴近存储或数据湖，允许多个应用程序共享缓存数据。D4N 的核心是基于分布式目录，负责维护整个缓存的全球状态。</p><h4 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h4><ul><li><strong>加速通用 S3 工作负载</strong>: 通过智能预取提升缓存效率。</li><li><strong>智能预取</strong>: 分析工作负载查询的 DAG，预先将对象从后端存储加载到缓存中。</li><li><strong>临时数据存储</strong>: 探索在缓存中存储临时数据，无需回写到后端存储。</li><li><strong>对象打包</strong>: 将小对象打包成大对象后再写回后端存储，减少 I/O 操作。</li></ul><h4 id="上游贡献与开发进展" tabindex="-1">上游贡献与开发进展 <a class="header-anchor" href="#上游贡献与开发进展" aria-label="Permalink to &quot;上游贡献与开发进展&quot;">​</a></h4><ul><li><strong>开发团队</strong>: 波士顿大学的 Amin、Sumatra 和 Cena，以及 IBM 的 Samara 和 Pra Shasta。</li><li><strong>当前状态</strong>: D4N 代码已由学生开发并测试，但需要重写以适配 RGW 当前架构。</li><li><strong>缓存架构</strong>: 基于 Zipper API，分为过滤器驱动、策略驱动、目录驱动和缓存后端驱动。当前支持 SST 和 Redis 作为缓存后端。</li><li><strong>目录驱动</strong>: 目前基于 Redis 服务器，已切换到 Valkyrie。</li></ul><h4 id="读缓存与写回缓存" tabindex="-1">读缓存与写回缓存 <a class="header-anchor" href="#读缓存与写回缓存" aria-label="Permalink to &quot;读缓存与写回缓存&quot;">​</a></h4><ul><li><strong>读缓存</strong>: 默认启用，仅缓存头块，数据块在读请求时缓存。</li><li><strong>写回缓存</strong>: 通过配置选项启用，缓存头块和数据块，支持单部分对象，多部分对象暂不支持。</li><li><strong>缓存一致性</strong>: 通过目录维护最新版本，删除操作支持延迟删除。</li></ul><h4 id="上游状态与未来工作" tabindex="-1">上游状态与未来工作 <a class="header-anchor" href="#上游状态与未来工作" aria-label="Permalink to &quot;上游状态与未来工作&quot;">​</a></h4><ul><li><strong>上游状态</strong>: 已合并基于 SST 后端的读缓存实验版本，写回缓存已引入头块缓存。</li><li><strong>未来工作</strong>: 实现分布式缓存，缓存分区，更多负载测试，探索更多缓存后端支持。</li></ul><h4 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h4><ul><li><strong>分析框架加速</strong>: 如 Hadoop 等，提升工作负载性能。</li><li><strong>S3 选择加速</strong>: 缓存对象的部分内容，加速 S3 Select 查询。</li><li><strong>灵活缓存策略</strong>: 用户可选择性缓存头块或数据块，或禁用多部分对象的缓存。</li></ul><h4 id="q-a-总结" tabindex="-1">Q&amp;A 总结 <a class="header-anchor" href="#q-a-总结" aria-label="Permalink to &quot;Q&amp;A 总结&quot;">​</a></h4><ul><li><strong>D4N 与 D3N 的区别</strong>: D4N 支持头块缓存，未来将支持分布式缓存，而 D3N 仍为单节点缓存。</li><li><strong>目录分布式实现</strong>: 未来将使用 Redis 集群，基于一致性哈希分布式存储对象。</li><li><strong>缓存一致性</strong>: 通过 Redis 集群维护最新版本，确保缓存一致性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续推进单节点写回缓存的上游工作。</li><li>完成分布式缓存的开发与测试。</li><li>进行更多负载测试，验证缓存性能并修复潜在问题。</li><li>探索更多缓存后端支持，如基于其他数据库的缓存后端。</li></ul>',20)])])}const p=t(l,[["render",o]]);export{u as __pageData,p as default};
